    function stopShareAnimation(){
      if(shareAnimationFrame)cancelAnimationFrame(shareAnimationFrame);shareAnimationFrame=0;shareAnimating=false;
    }
    function startShareAnimation(){
      stopShareAnimation();shareAnswer=null;shareChecked=false;shareAnimationReplay=false;
      if(matchMedia("(prefers-reduced-motion: reduce)").matches){const last=shanim(SHARE_ANIMATION.length-1);shareCg=last.cg;shareHookHeight=last.height;shareAnimationLabel=tr("Animation result","Resultado de la animación");shareAnimationDetail=last.detail;shareAnimationReplay=true;renderShareLab();return}
      shareAnimating=true;let started=0,lastPaint=0;const initialHold=650,stepMs=1800;
      const tick=now=>{
        if(!shareAnimating)return;if(now-lastPaint<32){shareAnimationFrame=requestAnimationFrame(tick);return}lastPaint=now;if(!started)started=now;const elapsed=now-started;
        if(elapsed<initialHold){const first=shanim(0);shareCg=first.cg;shareHookHeight=first.height;shareAnimationLabel=`1 ${tr("of","de")} ${SHARE_ANIMATION.length} · ${first.label}`;shareAnimationDetail=first.detail}
        else{const activeElapsed=elapsed-initialHold,segment=Math.floor(activeElapsed/stepMs);if(segment>=SHARE_ANIMATION.length-1){const last=shanim(SHARE_ANIMATION.length-1);shareCg=last.cg;shareHookHeight=last.height;shareAnimationLabel=tr("Animation complete","Animación completa");shareAnimationDetail=tr("Replay it, or adjust the CG and hook height manually to compare another case.","Repítala, o ajuste el CG y la altura del gancho manualmente para comparar otro caso.");shareAnimationReplay=true;stopShareAnimation();write("shareCg",shareCg);write("shareHookHeight",shareHookHeight);renderShareLab();return}const from=shanim(segment),to=shanim(segment+1),raw=(activeElapsed%stepMs)/stepMs,move=Math.min(1,raw/.72),eased=move<.5?2*move*move:1-Math.pow(-2*move+2,2)/2;shareCg=from.cg+(to.cg-from.cg)*eased;shareHookHeight=from.height+(to.height-from.height)*eased;shareAnimationLabel=`${segment+2} ${tr("of","de")} ${SHARE_ANIMATION.length} · ${to.label}`;shareAnimationDetail=to.detail}
        renderShareFrame();shareAnimationFrame=requestAnimationFrame(tick);
      };
      shareAnimationFrame=requestAnimationFrame(tick);
    }
