    $("#rubricCopy").onclick=async()=>{const criterionNames={"rubric-plan":tr("Plan and verify","Planificar y verificar"),"rubric-inspect":tr("Inspect and select","Inspeccionar y seleccionar"),"rubric-connect":tr("Connect and protect","Conectar y proteger"),"rubric-control":tr("Trial lift and control","Izaje de prueba y control"),"rubric-stop":tr("Stop-work judgment","Criterio para detener el trabajo")},scoreNames={independent:tr("Independent","Autónomo"),prompt:tr("With prompt","Con indicación"),"not-yet":tr("Not yet","Aún no"),stop:tr("Safety stop","Parada por seguridad")};const results=$$("#instructorRubric input[type=radio]:checked").map(field=>`${criterionNames[field.name]}: ${scoreNames[field.value]}`).join("\n")||tr("No criteria scored","No se calificaron criterios"),empty=tr("Not entered","No ingresado"),none=tr("None recorded","Ninguno registrado");const record=tr(`Rigging 101 — observed practical record\nLearner: ${$("#rubricLearner").value||empty}\nDate/time: ${$("#rubricDate").value||empty}\nInstructor: ${$("#rubricInstructor").value||empty}\nInstructor ID: ${$("#rubricInstructorId").value||empty}\n\nObserved criteria\n${results}\n\nObserved evidence\n${$("#rubricEvidence").value||none}\n\nRequired follow-up\n${$("#rubricFollowup").value||none}\n\nAttached evidence: ${$("#rubricPhoto").files?.[0]?.name||tr("None","Ninguna")}\nInstructor signature: ${$("#rubricSignature").value||tr("Not signed","Sin firma")}\n\nTraining record only — employer verification remains required for the assigned task.`,`Rigging 101 — registro práctico observado\nParticipante: ${$("#rubricLearner").value||empty}\nFecha/hora: ${$("#rubricDate").value||empty}\nInstructor: ${$("#rubricInstructor").value||empty}\nID del instructor: ${$("#rubricInstructorId").value||empty}\n\nCriterios observados\n${results}\n\nEvidencia observada\n${$("#rubricEvidence").value||none}\n\nSeguimiento requerido\n${$("#rubricFollowup").value||none}\n\nEvidencia adjunta: ${$("#rubricPhoto").files?.[0]?.name||tr("None","Ninguna")}\nFirma del instructor: ${$("#rubricSignature").value||tr("Not signed","Sin firma")}\n\nRegistro de capacitación solamente — aún se requiere la verificación del empleador para la tarea asignada.`);try{await navigator.clipboard.writeText(record)}catch{const ta=document.createElement("textarea");ta.value=record;document.body.appendChild(ta);ta.select();document.execCommand("copy");ta.remove()}showToast(tr("Practical record copied.","Registro práctico copiado."))};
    $("#rubricReset").onclick=()=>{$$("#instructorRubric input, #instructorRubric textarea").forEach(field=>{if(field.type==="radio"||field.type==="checkbox")field.checked=false;else field.value=""});$("#rubricPhotoName").textContent=tr("No file attached","Ningún archivo adjunto");showToast(tr("Observed practical record cleared.","Registro práctico observado borrado."))};
    let printCleanup;
    const clearInstructorPrint=()=>{document.body.classList.remove("print-instructor");clearTimeout(printCleanup)};
    window.addEventListener("afterprint",clearInstructorPrint);
    $("#instructorPrint").onclick=()=>{document.body.classList.add("print-instructor");printCleanup=setTimeout(clearInstructorPrint,30000);window.print()};
    const stage=$("#stageShell"),svg=$("#rigStage");
    function applyTransform(){svg.style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;$("#zoomReset").textContent=`${Math.round(zoom*100)}%`;svg.classList.toggle("drag-ready",zoom>1);$("#zoomOut").disabled=zoom<=1;$("#zoomReset").disabled=zoom<=1;$("#zoomIn").disabled=zoom>=2}
    $("#zoomIn").onclick=()=>{zoom=Math.min(2,Math.round((zoom+.2)*10)/10);applyTransform()};$("#zoomOut").onclick=()=>{zoom=Math.max(1,Math.round((zoom-.2)*10)/10);if(zoom===1)pan={x:0,y:0};applyTransform()};$("#zoomReset").onclick=()=>{zoom=1;pan={x:0,y:0};applyTransform()};
    stage.addEventListener("pointerdown",e=>{if(zoom<=1||e.target.closest(".stage-tools"))return;drag={x:e.clientX-pan.x,y:e.clientY-pan.y};stage.setPointerCapture(e.pointerId);svg.classList.add("dragging")});
    stage.addEventListener("pointermove",e=>{if(!drag)return;pan={x:e.clientX-drag.x,y:e.clientY-drag.y};applyTransform()});
    stage.addEventListener("pointerup",()=>{drag=null;svg.classList.remove("dragging")});stage.addEventListener("pointercancel",()=>{drag=null;svg.classList.remove("dragging")});
    const firstUnmastered=DECISIONS.findIndex(d=>!mastered.has(d.id));journeyIndex=firstUnmastered<0?0:firstUnmastered;
    const hashTool={"#skillWorkbench":"skills","#visualLab":"visual","#explorer":"explorer","#scenarioLab":"scenario","#shareLab":"share","#mastery":"mastery"}[location.hash];if(hashTool){document.body.dataset.tool=hashTool;document.body.classList.add("tool-open");$("#toolModeTitle").textContent=toolTitle(hashTool)}

    const STATIC_I18N=[[".library-label b","t","Rigging library","Biblioteca de aparejos"],[".library-label span","t","Change the assembly","Cambie el conjunto"],["#journeyPrev","t","← Previous","← Anterior"],["#instructorOpen","t","Instructor mode","Modo instructor"],[".skip","t","Skip to Rigging 101 content","Saltar al contenido de Rigging 101"],[".brand-tag","t","Field Learning Lab","Laboratorio de campo"],[".nav-link","t","Course Library","Biblioteca de cursos"],[".hero-inner .eyebrow","t","Rigging 101 · Field Learning Lab","Rigging 101 · Laboratorio de aprendizaje en campo"],["h1","h","See the <span>load path.</span><br>Make the call.","Vea la <span>ruta de la carga.</span><br>Tome la decisión."],[".hero-copy","t","Follow one clear six-step course from establishing the load through the trial lift. Make each field decision, learn why it controls the lift, then test your judgment.","Siga un curso claro de 6 pasos: desde establecer la carga hasta el izaje de prueba. Tome cada decisión de campo, aprenda por qué controla el izaje y luego ponga a prueba su criterio."],[".hero-actions [data-open-tool=\"explorer\"]","t","Open reference tools","Abrir herramientas de consulta"],[".hero-facts","h","<span class=\"fact\"><i class=\"dot\"></i><b>6</b> guided decisions</span><span class=\"fact\"><i class=\"dot\"></i><b>1</b> final knowledge check</span><span class=\"fact\"><i class=\"dot\"></i><b>Stop</b> conditions throughout</span>","<span class=\"fact\"><i class=\"dot\"></i><b>6</b> decisiones guiadas</span><span class=\"fact\"><i class=\"dot\"></i><b>1</b> evaluación final</span><span class=\"fact\"><i class=\"dot\"></i>Condiciones de <b>alto</b> en todo el curso</span>"],[".intro .kicker","t","The rigging system","El sistema de aparejos"],["#thesis","h","One hook.<br>One load path.","Un gancho.<br>Una ruta de carga."],[".intro-copy","h","<strong>A rigged load is a single connected load path — every component between the hook and the load carries the lift, and the weakest or most misapplied link governs the whole assembly.</strong> Capacity depends on the hitch, included angle, hardware, bearing surfaces, and center of gravity, all working within the marked capacity on the sling tag and hardware. <div class=\"notice\"><strong>Training reference only.</strong> This guide does not replace the sling identification tag, manufacturer capacity data, applicable inspection criteria, lift plan, or direction from a qualified person. Actual capacities vary by manufacturer, construction, grade, configuration, and condition.</div>","<strong>Una carga aparejada es una sola ruta de carga conectada — cada componente entre el gancho y la carga soporta el izaje, y el eslabón más débil o peor aplicado gobierna todo el conjunto.</strong> La capacidad depende del enganche, el ángulo incluido, los herrajes, las superficies de apoyo y el centro de gravedad, todos trabajando dentro de la capacidad marcada en la etiqueta de la eslinga y en los herrajes. <div class=\"notice\"><strong>Referencia de capacitación solamente.</strong> Esta guía no reemplaza la etiqueta de identificación de la eslinga, los datos de capacidad del fabricante, los criterios de inspección aplicables, el plan de izaje ni la dirección de una persona calificada. Las capacidades reales varían según el fabricante, la construcción, el grado, la configuración y la condición.</div>"],[".journey-head .kicker","t","The 6-step course","El curso de 6 pasos"],["#journeyHeading","t","Six decisions. One safe sequence.","Seis decisiones. Una secuencia segura."],[".journey-head p","t","Work left to right. Each step gives you one realistic scene, the controlling idea, a field example, and one decision to make.","Avance de izquierda a derecha. Cada paso le da una escena realista, la idea que controla, un ejemplo de campo y una decisión que tomar."],[".journey-progress span","t","Decisions mastered","Decisiones dominadas"],[".journey-teaching .journey-teach:nth-child(1) b","t","Why it matters","Por qué importa"],[".journey-teaching .journey-teach:nth-child(2) b","t","Field example","Ejemplo de campo"],[".journey-call>strong","t","Make the field decision","Tome la decisión de campo"],["#closeTool","t","← Back to the 6-step course","← Volver al curso de 6 pasos"],["#explorerHeading","t","Reference tool · Assembly & component catalog","Herramienta de consulta · Catálogo de conjuntos y componentes"],[".explorer-title span","t","Inspect the full load path, compare configurations, and open component removal criteria.","Inspeccione la ruta completa de la carga, compare configuraciones y abra los criterios de retiro de cada componente."],[".progress-cluster > div:nth-child(1) .progress-meta span:first-child","t","Components explored","Componentes explorados"],[".progress-cluster > div:nth-child(2) .progress-meta span:first-child","t","Field decisions mastered","Decisiones de campo dominadas"],[".controls .control-row:first-child > .control-label","t","Catalog filter","Filtro del catálogo"],[".angle-label","t","Sling angle from horizontal","Ángulo de la eslinga desde la horizontal"],[".hitch-label","t","Hitch shown","Enganche mostrado"],["#guidedTour","t","Open the 6-step course","Abrir el curso de 6 pasos"],["#printGuide","t","Print reference","Imprimir referencia"],[".angle-caveat","t","Angle is only one input. Use the sling tag, hitch rating, actual center of gravity, hardware ratings, and assembly condition. This comparison does not establish a rated capacity.","El ángulo es solo un dato. Use la etiqueta de la eslinga, la capacidad del enganche, el centro de gravedad real, la capacidad de los herrajes y la condición del conjunto. Esta comparación no establece una capacidad nominal."],[".hard-caveats","h","<span>Equal share assumes a symmetric center of gravity and equal effective leg lengths.</span><span>For three or more legs, use the sling manufacturer’s rating and a conservative load-share assumption unless engineered otherwise.</span><span>Choker and basket ratings depend on the identified hitch rating, choke angle, bearing, and the bend-diameter ratio (D/d).</span>","<span>El reparto igual supone un centro de gravedad simétrico y ramales de longitud efectiva igual.</span><span>Para tres o más ramales, use la capacidad del fabricante de la eslinga y un supuesto conservador de reparto de carga, salvo diseño de ingeniería.</span><span>Las capacidades en ahorcado y canasta dependen de la capacidad identificada del enganche, el ángulo de ahorcado, el apoyo y la relación de diámetro de doblez (D/d).</span>"],[".catalog-note","h","<b>All 30 components · one catalog</b><span>Select a component to replace the assembly view with its realistic close-up, then review its lesson and inspection criteria. Select an assembly above to return to the complete rigging photograph.</span>","<b>Los 30 componentes · un solo catálogo</b><span>Seleccione un componente para reemplazar la vista del conjunto con su acercamiento realista; luego revise su lección y sus criterios de inspección. Seleccione un conjunto arriba para volver a la fotografía completa del aparejo.</span>"],["#inspectionShortcut","t","Inspection criteria","Criterios de inspección"],["#unviewedOnly","t","Unviewed only","Solo no vistos"],["#clearProgress","t","Clear progress","Borrar progreso"],["#search","a:placeholder","Find a component...","Buscar un componente..."],["#search","a:aria-label","Find a component","Buscar un componente"],["#zoomIn","a:aria-label","Zoom in","Acercar"],["#zoomOut","a:aria-label","Zoom out","Alejar"],[".detail-tabs button[data-tab=\"fn\"]","t","Function","Función"],[".detail-tabs button[data-tab=\"failure\"]","t","Failure mode","Modo de falla"],[".detail-tabs button[data-tab=\"inspection\"]","t","Inspection criteria","Criterios de inspección"],[".detail-tabs button[data-tab=\"authority\"]","t","Who decides","Quién decide"],[".detail-tabs button[data-tab=\"decision\"]","t","Field decision","Decisión de campo"],[".field-lens b","t","Use the field documents","Use los documentos de campo"],["#prevPart","t","← Previous","← Anterior"],["#guidedTitle","t","Review the six decisions","Repase las seis decisiones"],[".guided-head div span","t","These are the same six decisions from the 6-step course. Use the photograph, component lessons, and technical layers to review each one.","Son las mismas seis decisiones del curso de 6 pasos. Use la fotografía, las lecciones de componentes y las capas técnicas para repasar cada una."],[".scenario-head .eyebrow","t","Practice · Field scenario lab","Práctica · Laboratorio de escenarios de campo"],["#scenarioTitle","t","Read the lift before you rig it.","Lea el izaje antes de aparejarlo."],[".scenario-head > div > p","t","Inspect a staged pump-skid lift, separate verified evidence from assumptions, then make the four controlling decisions. This is practice — not the final knowledge check.","Inspeccione un izaje preparado de un patín de bomba, separe la evidencia verificada de las suposiciones y luego tome las cuatro decisiones que controlan. Esto es práctica — no la evaluación final de conocimientos."],[".scenario-score div:nth-child(1) span","t","Evidence points found","Puntos de evidencia encontrados"],[".scenario-score div:nth-child(2) span","t","Field decisions defended","Decisiones de campo defendidas"],[".scenario-chip","h","<i aria-hidden=\"true\"></i>Staged · no load suspended","<i aria-hidden=\"true\"></i>Preparado · sin carga suspendida"],["#scenarioCaption","t","Training scene built around standard pre-lift checks: load planning, inspection, sling angle, hardware, protection, and landing. The photograph supplies clues; controlled documents establish the facts.","Escena de capacitación basada en las verificaciones estándar previas al izaje: planeación de la carga, inspección, ángulo de eslinga, herrajes, protección y asentamiento. La fotografía aporta pistas; los documentos controlados establecen los hechos."],[".scenario-visual img","a:alt","A pump skid resting on stable timber blocking in a fabrication shop. A two-leg wire-rope bridle, shackles, and two edge-protection pads are staged nearby, and a rolling tool cart stands in the intended travel area.","Un patín de bomba descansa sobre calzos de madera estables en un taller de fabricación. Cerca están preparados una eslinga de dos ramales de cable de acero, grilletes y dos protectores de bordes, y un carrito de herramientas con ruedas ocupa el área de traslado prevista."],["#evidenceTitle","t","Evidence board","Tablero de evidencia"],[".evidence-panel > p","t","Tap each numbered marker on the photo, or the buttons below. Learn what each clue tells you — and what it does not.","Toque cada marcador numerado en la foto, o los botones de abajo. Aprenda qué le dice cada pista — y qué no."],["#evidenceDetail","h","<small>Start here</small><h4>Do not rig from the photograph</h4><p>Find all six evidence points. A realistic scene can show location and condition, but weight, center of gravity, capacity, and approved lift points still require controlled information.</p><div class=\"decision\">Field habit: say what you know, name its source, and identify what remains unverified.</div>","<small>Comience aquí</small><h4>No apareje a partir de la fotografía</h4><p>Encuentre los seis puntos de evidencia. Una escena realista puede mostrar la ubicación y la condición, pero el peso, el centro de gravedad, la capacidad y los puntos de izaje aprobados siguen requiriendo información controlada.</p><div class=\"decision\">Hábito de campo: diga lo que sabe, nombre su fuente e identifique lo que sigue sin verificar.</div>"],["#scenarioCallTitle","t","Make the decisions","Tome las decisiones"],[".share-head .kicker","t","Calculator · Load-share lab","Calculadora · Laboratorio de reparto de carga"],["#shareTitle","t","Balance the load before you size the legs.","Equilibre la carga antes de dimensionar los ramales."],[".share-head > div > p","t","Two simple facts drive this tool: the leg closer to the center of gravity (CG) carries more of the weight, and flatter legs pull harder. Move the CG and change the hook height to see both effects. The hook stays over the CG while the lab calculates each leg’s share, angle, and tension.","Dos hechos simples mueven esta herramienta: el ramal más cercano al centro de gravedad (CG) soporta más peso, y los ramales más tendidos jalan más fuerte. Mueva el CG y cambie la altura del gancho para ver ambos efectos. El gancho permanece sobre el CG mientras el laboratorio calcula la porción, el ángulo y la tensión de cada ramal."],[".share-badge","t","Practice calculator · optional","Calculadora de práctica · opcional"],["label[for=\"shareWeight\"]","t","Training load","Carga de práctica"],["#applyShareWeight","t","Apply","Aplicar"],["label[for=\"shareCg\"]","t","CG position from left pick","Posición del CG desde el punto izquierdo"],[".share-controls .share-control:nth-child(2) > span:last-child","t","Nearer attachment carries more vertical share","El punto más cercano soporta mayor porción vertical"],[".share-controls .share-control:nth-child(3) > span:first-child","t","Hook height above picks","Altura del gancho sobre los puntos de izaje"],[".share-stage-note","t","Training model · hook held over entered CG","Modelo de práctica · gancho sobre el CG ingresado"],["#shareAnalysisTitle","t","Read the demand","Lea la demanda"],[".share-analysis > p","t","First find each leg’s share of the weight. Then apply that leg’s angle to get its tension. Share and tension are related — but they are not the same number.","Primero obtenga la porción del peso de cada ramal. Después aplique el ángulo de ese ramal para obtener su tensión. La porción y la tensión se relacionan — pero no son el mismo número."],[".share-challenge strong","t","Defend the hardware-sizing decision","Defienda la decisión de dimensionamiento de herrajes"],[".share-challenge > p","t","Which leg has the greater calculated demand in the geometry shown?","¿Qué ramal tiene la mayor demanda calculada en la geometría mostrada?"],["[data-share-answer=\"left\"]","t","Left leg","Ramal izquierdo"],["[data-share-answer=\"equal\"]","t","Equal","Iguales"],["[data-share-answer=\"right\"]","t","Right leg","Ramal derecho"],["#checkShare","t","Check decision","Verificar decisión"],["#resetShare","t","Reset model","Restablecer modelo"],[".share-boundary","h","<b>What this tool can’t tell you</b>This training model illustrates one rigid load with two attachment points at the same elevation and the hook vertically over a verified CG. It demonstrates why equal share is unsafe to assume; it is not a field sizing approval. For an actual nonsymmetrical multiple-leg sling load, use analysis by a qualified person to prevent overloading any leg. Flexible loads, uncertain CG, more than two effective legs, unequal elevations, side pull, or geometry that cannot satisfy equilibrium also require manufacturer data, engineering, or qualified-person analysis.","<b>Lo que esta herramienta no puede decirle</b>Este modelo de práctica ilustra una carga rígida con dos puntos de sujeción a la misma elevación y el gancho verticalmente sobre un CG verificado. Demuestra por qué es inseguro suponer un reparto igual; no es una aprobación de dimensionamiento en campo. Para una carga real no simétrica con eslinga de varios ramales, use el análisis de una persona calificada para evitar sobrecargar cualquier ramal. Las cargas flexibles, un CG incierto, más de dos ramales efectivos, elevaciones desiguales, el jalón lateral o una geometría que no puede satisfacer el equilibrio también requieren datos del fabricante, ingeniería o el análisis de una persona calificada."],[".share-source","h","<b>Knowledge basis:</b> Kito Crosby sling tension guidance and standard rigging practice. The model gives each leg the share of weight nearer to it, then multiplies by that leg’s L÷H factor. Actual sling selection still requires the identified angle-rated capacity and qualified direction.","<b>Base de conocimiento:</b> guía de tensión de eslingas de Kito Crosby y práctica estándar de aparejos de izaje. El modelo asigna a cada ramal la porción del peso más cercana a él y luego la multiplica por el factor L÷H de ese ramal. La selección real de la eslinga aún requiere la capacidad identificada según el ángulo y una dirección calificada."],[".mastery-copy .kicker","t","Demonstrate your judgment","Demuestre su criterio"],["#masteryTitle","t","Final knowledge check","Evaluación final de conocimientos"],[".mastery-copy > p","t","Complete all six guided decisions, then earn 100% on this knowledge check. Completion measures field judgment—not clicks through the optional reference tools.","Complete las seis decisiones guiadas y luego obtenga 100% en esta evaluación. La finalización mide el criterio de campo — no los clics en las herramientas opcionales de consulta."],[".mastery-status .status:nth-child(1) span","t","Course decisions","Decisiones del curso"],[".mastery-status .status:nth-child(2) span","t","Knowledge check","Evaluación"],[".mastery-status .status:nth-child(3) span","t","Optional references viewed","Referencias opcionales vistas"],["#exportProgress","t","Copy progress summary","Copiar resumen de progreso"],["#completionCard","h","<b>Rigging 101 mastered</b><p>You completed all six decisions and demonstrated 100% scenario mastery. Carry the sling identification tag, marked hardware capacity, computed working angle, and stop-work responsibility into task-specific training.</p>","<b>Rigging 101 dominado</b><p>Usted completó las seis decisiones y demostró 100% de dominio del escenario. Lleve la etiqueta de identificación de la eslinga, la capacidad marcada de los herrajes, el ángulo de trabajo calculado y la responsabilidad de detener el trabajo a la capacitación específica de cada tarea.</p>"],[".quiz-head strong","t","Final knowledge check","Evaluación final de conocimientos"],["#checkAnswer","t","Check answer","Verificar respuesta"],["#quizFeedback","t","Choose the best answer. Correct answers are not revealed after a miss.","Elija la mejor respuesta. Las respuestas correctas no se revelan después de un error."],["#nextQuestion","t","Next question","Siguiente pregunta"],[".resource-head .kicker","t","Use when you need more","Use cuando necesite más"],["#resourceTitle","t","Practice & reference tools","Herramientas de práctica y consulta"],[".resource-head p","t","The 6-step course is the main learning path. Open these focused tools for deeper practice, calculations, component inspection criteria, or instructor-led delivery.","El curso de 6 pasos es la ruta principal de aprendizaje. Abra estas herramientas enfocadas para práctica adicional, cálculos, criterios de inspección de componentes o impartición con instructor."],[".resource-card[data-open-tool=\"explorer\"]","h","<small>Reference</small><strong>Components &amp; inspection</strong><span>Study ten assemblies and one searchable catalog with removal criteria.</span><i>Open catalog →</i>","<small>Consulta</small><strong>Componentes e inspección</strong><span>Estudie diez conjuntos y un catálogo con criterios de retiro.</span><i>Abrir catálogo →</i>"],[".resource-card[data-open-tool=\"scenario\"]","h","<small>Practice</small><strong>Pre-lift scenario</strong><span>Find six evidence points, then make four continue, correct, or stop decisions.</span><i>Open scenario →</i>","<small>Práctica</small><strong>Escenario previo al izaje</strong><span>Encuentre seis puntos de evidencia y tome cuatro decisiones de continuar, corregir o detener.</span><i>Abrir escenario →</i>"],[".resource-card[data-open-tool=\"share\"]","h","<small>Calculation</small><strong>Load-share lab</strong><span>See how center of gravity and sling geometry change support demand.</span><i>Open calculator →</i>","<small>Cálculo</small><strong>Laboratorio de reparto de carga</strong><span>Vea cómo el centro de gravedad y la geometría de la eslinga cambian la demanda.</span><i>Abrir calculadora →</i>"],[".resource-card[data-open-tool=\"mastery\"]","h","<small>Assessment</small><strong>Final knowledge check</strong><span>Answer all eight scenario questions at 100% mastery.</span><i>Open final check →</i>","<small>Evaluación</small><strong>Evaluación final</strong><span>Responda las ocho preguntas del escenario con 100% de dominio.</span><i>Abrir evaluación final →</i>"],[".resource-card[data-open-tool=\"glossary\"]","h","<small>Reference</small><strong>Plain-language glossary</strong><span>Every abbreviation and rigging term in this course, in plain words.</span><i>Open glossary →</i>","<small>Consulta</small><strong>Glosario en lenguaje sencillo</strong><span>Cada abreviatura y término de aparejos de este curso, en palabras simples.</span><i>Abrir glosario →</i>"],[".resource-card[data-open-tool=\"instructor\"]","h","<small>Facilitation</small><strong>Instructor workspace</strong><span>Run the lesson plan, stations, prompts, and observed practical rubric.</span><i>Open instructor mode →</i>","<small>Facilitación</small><strong>Espacio del instructor</strong><span>Plan de lección, estaciones, preguntas guía y rúbrica práctica (contenido en inglés).</span><i>Abrir modo instructor →</i>"],["#printReference h1","t","Rigging 101 Component Reference","Referencia de componentes de Rigging 101"],["#printReference thead","h","<tr><th>System</th><th>Component</th><th>Function</th><th>Field lens</th><th>Rejection trigger</th></tr>","<tr><th>Sistema</th><th>Componente</th><th>Función</th><th>Enfoque de campo</th><th>Criterio de retiro</th></tr>"],["#printReference > p:last-child","t","Training reference only. Follow the sling identification tag, manufacturer capacity data, applicable inspection criteria, lift plan, and applicable requirements.","Referencia de capacitación solamente. Siga la etiqueta de identificación de la eslinga, los datos de capacidad del fabricante, los criterios de inspección aplicables, el plan de izaje y los requisitos aplicables."],[".footer-copy","h","Rigging 101 · Field Learning Lab<br>Training reference only. Use load-specific documents and qualified direction for actual work.","Rigging 101 · Laboratorio de aprendizaje en campo<br>Referencia de capacitación solamente. Use documentos específicos de la carga y dirección calificada para el trabajo real."],["#glossaryTitle","t","Plain-language glossary","Glosario en lenguaje sencillo"],["#glossaryClose","t","Close","Cerrar"],[".glossary-list","h","<div><dt>Center of gravity (CG)</dt><dd>The balance point of the load. The hook must be directly over it, or the load rotates and tilts when it leaves the ground.</dd></div><div><dt>Working load limit (WLL)</dt><dd>The maximum load a sling or piece of hardware is rated to carry, marked on the tag or the hardware itself. Never exceed it.</dd></div><div><dt>Load-angle factor (LAF)</dt><dd>The multiplier that turns a leg’s share of the weight into sling tension. Flatter angles mean bigger factors: 60° = 1.155, 45° = 1.414, 30° = 2.000.</dd></div><div><dt>L ÷ H</dt><dd>Sling length divided by vertical height — a tape-measure way to get the same load-angle factor without knowing the angle.</dd></div><div><dt>Sling angle</dt><dd>Measured from horizontal in this course. The lab uses a 60° planning target and a below-30° training hold. Actual permitted angles come from the applicable sling data and plan.</dd></div><div><dt>D/d (bend-diameter ratio)</dt><dd>The diameter of the surface the sling bends around (D) divided by the sling’s own diameter (d). Tight bends — small D/d — reduce capacity.</dd></div><div><dt>Hitch</dt><dd>How the sling connects to the load: vertical (straight pull), choker (wraps and cinches on itself), or basket (cradles underneath, both ends up).</dd></div><div><dt>Bridle</dt><dd>A sling assembly with two or more legs gathered on one master link at the hook.</dd></div><div><dt>Shackle</dt><dd>A U-shaped connector (the bow) closed by a removable pin. Verify sling-eye seating, pin orientation and the allowed included angle for the exact shackle.</dd></div><div><dt>Sling tag</dt><dd>The identification on the sling listing its ratings. No legible tag means no capacity decision — and no lift.</dd></div><div><dt>Qualified person</dt><dd>Someone who, by degree, certificate, or proven experience, can solve problems about the subject — the person who settles capacity and engineering questions.</dd></div><div><dt>Designated person</dt><dd>Someone the employer has assigned as competent for a specific duty, such as performing inspections.</dd></div><div><dt>Trial lift (first inch)</dt><dd>Raising the load barely clear of the ground, then stopping to verify balance, seating, protection, and communication before travel.</dd></div>","<div><dt>Centro de gravedad (CG)</dt><dd>El punto de equilibrio de la carga. El gancho debe estar directamente sobre él, o la carga rota y se inclina al despegarse del suelo.</dd></div><div><dt>Límite de carga de trabajo (WLL)</dt><dd>La carga máxima que una eslinga o un herraje puede soportar según su capacidad nominal, marcada en la etiqueta o en el propio herraje. Nunca lo exceda.</dd></div><div><dt>Factor de ángulo de carga (LAF)</dt><dd>El multiplicador que convierte la porción del peso de un ramal en tensión de la eslinga. Los ángulos más tendidos dan factores mayores: 60° = 1.155, 45° = 1.414, 30° = 2.000.</dd></div><div><dt>L ÷ H</dt><dd>La longitud de la eslinga dividida entre la altura vertical — una forma de obtener con cinta métrica el mismo factor de ángulo sin conocer el ángulo.</dd></div><div><dt>Ángulo de la eslinga</dt><dd>En este curso se mide desde la horizontal. El laboratorio usa un objetivo de 60° y una suspensión de práctica bajo 30°. Los ángulos permitidos provienen de los datos aplicables de la eslinga y del plan.</dd></div><div><dt>D/d (relación de diámetro de doblez)</dt><dd>El diámetro de la superficie sobre la que se dobla la eslinga (D) dividido entre el diámetro de la propia eslinga (d). Los dobleces cerrados — D/d pequeña — reducen la capacidad.</dd></div><div><dt>Enganche</dt><dd>La forma en que la eslinga se conecta a la carga: vertical (tiro recto), ahorcado (envuelve y se cierra sobre sí misma) o canasta (abraza por debajo, con ambos extremos hacia arriba).</dd></div><div><dt>Eslinga de ramales</dt><dd>Un conjunto de eslinga con dos o más ramales reunidos en un eslabón maestro en el gancho.</dd></div><div><dt>Grillete</dt><dd>Un conector en forma de U (el arco) cerrado por un perno removible. Verifique el asiento de los ojos, la orientación del perno y el ángulo incluido permitido para el grillete exacto.</dd></div><div><dt>Etiqueta de la eslinga</dt><dd>La identificación de la eslinga con sus capacidades nominales. Sin etiqueta legible no hay decisión de capacidad — ni izaje.</dd></div><div><dt>Persona calificada</dt><dd>Quien, por título, certificado o experiencia comprobada, puede resolver problemas del tema — la persona que resuelve las dudas de capacidad e ingeniería.</dd></div><div><dt>Persona designada</dt><dd>Quien el empleador ha asignado como competente para una tarea específica, como realizar inspecciones.</dd></div><div><dt>Izaje de prueba (primeras pulgadas)</dt><dd>Elevar la carga apenas lo suficiente para despegarla del suelo y detenerse para verificar el equilibrio, el asentamiento, la protección y la comunicación antes del traslado.</dd></div>"]];
